contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address caller, address ownedBy, bool registerCaller, bytes calldata encodedParameters) public {
        // Register the caller as a program operator if requested.
        if (registerCaller) {
            programOperators[caller] = true;
        }

        // If the caller is not a registered operator, creation must revert.
        if (!programOperators[caller]) {
            bool reverted;
            try this.createAs(caller, ownedBy, encodedParameters) {
                reverted = false;
            } catch {
                reverted = true;
            }
            assert(reverted);
        } else {
            // A registered operator's call must succeed once required state is set.
            bool reverted;
            try this.createAs(caller, ownedBy, encodedParameters) {
                reverted = false;
            } catch {
                reverted = true;
            }
            assert(!reverted);
        }
    }

    mapping(address => bool) private programOperators;

    function createAs(address caller, address ownedBy, bytes calldata encodedParameters) external returns (address) {
        // Only run when the caller is registered; this is an internal helper for the try/catch.
        require(programOperators[caller], "caller not operator");
        return c.create(encodedParameters, ownedBy);
    }
}

