contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address operator, address ownedBy, bytes calldata encodedParameters) public {
        // Register the caller as a program operator and set a nonzero implementation.
        c.programOperators(operator);
        c.updateAlloSettings(address(0x1234));
        c.updateRoundImplementation(payable(address(0xdead)));

        // Make the calling contract the program operator for the create call.
        address prevOperator = operator;
        (bool ok, ) = address(c).call(abi.encodeWithSignature("programOperators(address)", address(this)));
        require(ok, "operator setup failed");

        // Use the factory's public getter to confirm the implementation that create will clone.
        address impl = c.roundImplementation();
        require(impl != address(0), "implementation must be nonzero");

        // create may revert if the clone's initialize does not succeed for these parameters.
        bool reverted;
        address clone;
        try c.create(encodedParameters, ownedBy) returns (address returnedClone) {
            clone = returnedClone;
            reverted = false;
        } catch {
            reverted = true;
        }

        // General rule: if create does not revert, it must return a nonzero clone address
        // that has contract code and is distinct from the factory itself.
        assert(
            reverted ||
            (clone != address(0) && clone.code.length > 0 && clone != address(c))
        );
    }
}

