contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address target, address impl, address settings) public {
        bool initialized;
        try c.initialize() {
            initialized = true;
        } catch {
            initialized = false;
        }
        require(initialized);

        bool implOk = true;
        if (impl != address(0)) {
            try c.updateRoundImplementation(payable(impl)) { implOk = true; } catch { implOk = false; }
        }
        require(implOk);

        bool settingsOk = true;
        if (settings != address(0)) {
            try c.updateAlloSettings(settings) { settingsOk = true; } catch { settingsOk = false; }
        }
        require(settingsOk);

        address r = c.roundImplementation();
        address a = c.alloSettings();
        bool isCallerOperator = c.programOperators(address(this));

        bool canCreate;
        if (r == address(0) || a == address(0) || !isCallerOperator) {
            canCreate = false;
        } else {
            canCreate = true;
        }

        bool reverted;
        try c.create(hex"", target) returns (address) {
            reverted = false;
        } catch {
            reverted = true;
        }

        assert(reverted != canCreate);
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(
        address newImpl,
        address newSettings,
        address operator,
        bytes calldata encodedParameters,
        address ownedBy,
        address arbitraryCaller
    ) public payable {
        require(newImpl != address(0), "newImpl zero");
        require(newSettings != address(0), "newSettings zero");
        require(operator != address(0), "operator zero");

        // The test contract owns c; authorize a distinct program operator.
        c.updateRoundImplementation(payable(newImpl));
        c.updateAlloSettings(newSettings);
        (bool okSetOp, ) = address(c).call(
            abi.encodeWithSignature("setProgramOperator(address,bool)", operator, true)
        );
        require(okSetOp, "setProgramOperator unavailable");

        // Ensure that an operator calling create succeeds (return value check).
        address returnedClone = c.create(encodedParameters, ownedBy);

        // c's public state must be unchanged by create().
        assert(
            c.roundImplementation() == newImpl &&
            c.alloSettings() == newSettings &&
            c.programOperators(operator) &&
            !c.programOperators(arbitraryCaller) &&
            returnedClone != address(0)
        );
    }

    receive() external payable {}
}

